module UniFFILib
  class ForeignBytes < FFI::Struct
    layout :len,      :int32,
           :data,     :pointer

    def len
      self[:len]
    end

    def data
      self[:data]
    end

    def to_s
      "ForeignBytes(len=#{len}, data=#{data.read_bytes(len)})"
    end
  end
end

private_constant :UniFFILib
  
# Helper for structured reading of values from a RustBuffer.
class RustBufferStream

  def initialize(rbuf)
    @rbuf = rbuf
    @offset = 0
  end

  def remaining
    @rbuf.len - @offset
  end

  def read(size)
    raise InternalError, 'read past end of rust buffer' if @offset + size > @rbuf.len

    data = @rbuf.data.get_bytes @offset, size

    @offset += size

    data
  end

  def read_u8
    unpack_from 1, 'c'
  end

  def read_u16
    unpack_from 2, 'S>'
  end

  def read_i16
    unpack_from 2, 's>'
  end

  def read_u32
    unpack_from 4, 'L>'
  end

  def read_u64
    unpack_from 8, 'Q>'
  end

  def read_i64
    unpack_from 8, 'q>'
  end

  def read_f32
    unpack_from 4, 'g'
  end

  def read_f64
    unpack_from 8, 'G'
  end

  def read_bool
    v = unpack_from 1, 'c'

    return false if v == 0
    return true if v == 1

    raise InternalError, 'Unexpected byte for Boolean type'
  end

  def read_string
    size = unpack_from 4, 'l>'

    raise InternalError, 'Unexpected negative string length' if size.negative?

    read(size).force_encoding(Encoding::UTF_8)
  end

  def read_bytes
    size = unpack_from 4, 'l>'

    raise InternalError, 'Unexpected negative byte string length' if size.negative?

    read(size).force_encoding(Encoding::BINARY)
  end

  # The Object type DataStore.

  def read_TypeDataStore
    handle = unpack_from 8, 'Q>'
    return DataStore.uniffi_lift(handle)
  end

  # The Object type MeshServices.

  def read_TypeMeshServices
    handle = unpack_from 8, 'Q>'
    return MeshServices.uniffi_lift(handle)
  end

  # The Object type OfflineProtocol.

