  # Record type AckConfig
class AckConfig
  attr_reader :default_timeout_ms, :max_pending_acks

  def initialize(default_timeout_ms:, max_pending_acks:)
    @default_timeout_ms = default_timeout_ms
    @max_pending_acks = max_pending_acks
  end

  def ==(other)
    if @default_timeout_ms != other.default_timeout_ms
      return false
    end
    if @max_pending_acks != other.max_pending_acks
      return false
    end

    true
  end
  
end
  
  # Record type BleFragment
class BleFragment
  attr_reader :recipient_id, :data

  def initialize(recipient_id:, data:)
    @recipient_id = recipient_id
    @data = data
  end

  def ==(other)
    if @recipient_id != other.recipient_id
      return false
    end
    if @data != other.data
      return false
    end

    true
  end
  
end
  
  # Record type CustodyConfig
class CustodyConfig
  attr_reader :enabled, :hold_ms, :max_entries_per_depositor, :max_bytes_per_depositor, :max_entries, :max_bytes, :stranger_max_entries, :stranger_max_bytes, :overflow_policy

  def initialize(enabled: nil, hold_ms: nil, max_entries_per_depositor: nil, max_bytes_per_depositor: nil, max_entries: nil, max_bytes: nil, stranger_max_entries: nil, stranger_max_bytes: nil, overflow_policy: nil)
    @enabled = enabled
    @hold_ms = hold_ms
    @max_entries_per_depositor = max_entries_per_depositor
    @max_bytes_per_depositor = max_bytes_per_depositor
    @max_entries = max_entries
    @max_bytes = max_bytes
    @stranger_max_entries = stranger_max_entries
    @stranger_max_bytes = stranger_max_bytes
    @overflow_policy = overflow_policy
  end

  def ==(other)
    if @enabled != other.enabled
      return false
    end
    if @hold_ms != other.hold_ms
      return false
    end
    if @max_entries_per_depositor != other.max_entries_per_depositor
      return false
    end
    if @max_bytes_per_depositor != other.max_bytes_per_depositor
      return false
    end
    if @max_entries != other.max_entries
      return false
    end
    if @max_bytes != other.max_bytes
      return false
    end
    if @stranger_max_entries != other.stranger_max_entries
      return false
    end
    if @stranger_max_bytes != other.stranger_max_bytes
      return false
    end
    if @overflow_policy != other.overflow_policy
      return false
    end

    true
  end
  
end
  
